[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Path)
$x=Get-Content (Join-Path $Path 'project-story.json') -Raw|ConvertFrom-Json;$keys=@();foreach($p in @($x.pages)){ $txt=Get-Content (Join-Path $Path $p.sourcePath) -Raw;if($txt -notmatch "parent:\s*$([regex]::Escape([string]$p.parent))"){throw 'PORTABLE_PAGE_METADATA_PARENT'}};foreach($e in @($x.graph)){$k="$($e.from)|$($e.to)|$($e.type)";if($keys -contains $k){throw 'PORTABLE_GRAPH_DUPLICATE'};$keys+=$k};foreach($h in @($x.hypercare)){if(@($h.tickets).Count -eq 0 -or [string]::IsNullOrWhiteSpace($h.diagnosis)-or [string]::IsNullOrWhiteSpace($h.fix)-or [string]::IsNullOrWhiteSpace($h.retest)){throw 'PORTABLE_HYPERCARE_FIELDS'}};Write-Host 'PASS: Portable structural gates.'
